# 1. Fechar recursão — BIND (named.conf)
acl "redes-internas" { 200.130.0.0/16; 10.0.0.0/8; localhost; };

options {
    allow-query        { any; };            # autoritativo p/ todos
    allow-recursion    { redes-internas; }; # recursão só interna
    recursion          yes;
    additional-from-cache no;
};

# 2. Response Rate Limiting no autoritativo
rate-limit {
    responses-per-second 15;   # respostas idênticas por cliente/s
    window 5;
    slip 2;                    # 1 em cada 2 excedentes vira TC=1
    log-only no;
};
# slip força o cliente legítimo a repetir em TCP, o que
# o refletor spoofado não consegue fazer

# 3. Recusar consultas ANY (RFC 8482)
minimal-any yes;

# 4. BCP38 na borda — impedir sair pacote com origem forjada
#    Cisco:
 interface GigabitEthernet0/1
  ip verify unicast source reachable-via rx
#    Linux:
 net.ipv4.conf.all.rp_filter = 1

# 5. Verificar se você é um refletor aberto
$ dig +short ANY isc.org @SEU.IP.PUBLICO
#   resposta = resolver aberto = precisa corrigir hoje
